//! RED #60: Rust client certificate transport, standard rustls TLS1.3 only.
//! X.509 credentials are generated by OpenSSL within a fresh test directory;
//! no private client CA/key is checked in or printed in test output.
use rystemdb_client::{ClientError, LocalClient};
use rystemdb_protocol::{read_frame, write_frame, Frame, Operation};
use std::fs;
use std::io::Write;
use std::net::TcpListener;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::Arc;
use std::thread;
use std::time::{Duration, SystemTime, UNIX_EPOCH};

static NEXT: AtomicUsize = AtomicUsize::new(0);
const TOKEN: [u8; 32] = [0x11; 32];

struct Temp(PathBuf);
impl Temp {
    fn new() -> Self {
        let nanos = SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos();
        let n = NEXT.fetch_add(1, Ordering::Relaxed);
        let dir = std::env::temp_dir().join(format!("rystem-sdk-mtls-{}-{nanos}-{n}", std::process::id()));
        fs::create_dir(&dir).unwrap();
        Self(dir)
    }
    fn path(&self, name: &str) -> PathBuf { self.0.join(name) }
}
impl Drop for Temp { fn drop(&mut self) { let _ = fs::remove_dir_all(&self.0); } }

fn fixture_path(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/tls").join(name)
}
fn openssl(args: &[&str]) {
    let output = Command::new("openssl").args(args)
        .stdout(Stdio::null()).stderr(Stdio::null()).output()
        .expect("test runner needs OpenSSL to create ephemeral, private client credentials");
    assert!(output.status.success(), "test-only OpenSSL certificate generation failed");
}
fn test_identity(dir: &Temp) {
    fs::write(dir.path("ca.cnf"),
        "[req]\ndistinguished_name=dn\nprompt=no\nx509_extensions=v3_ca\n[dn]\nCN=Rystem ephemeral TEST client CA\n[v3_ca]\nbasicConstraints=critical,CA:TRUE\nkeyUsage=critical,keyCertSign,cRLSign\n").unwrap();
    fs::write(dir.path("client.cnf"),
        "[v3_client]\nbasicConstraints=critical,CA:FALSE\nkeyUsage=critical,digitalSignature\nextendedKeyUsage=clientAuth\nsubjectAltName=URI:spiffe://rystemdb.local/client/writer\n").unwrap();
    let ca_key=dir.path("ca.key"); let ca_cert=dir.path("ca.pem");
    let leaf_key=dir.path("client.key"); let csr=dir.path("client.csr"); let leaf=dir.path("client.pem");
    // Keep the owned UTF-8 names alive across the OpenSSL argv calls.
    let ca_key_s=ca_key.to_str().unwrap().to_owned();
    let ca_cert_s=ca_cert.to_str().unwrap().to_owned();
    let leaf_key_s=leaf_key.to_str().unwrap().to_owned();
    let csr_s=csr.to_str().unwrap().to_owned();
    let leaf_s=leaf.to_str().unwrap().to_owned();
    let ca_cfg_s=dir.path("ca.cnf").to_str().unwrap().to_owned();
    let leaf_cfg_s=dir.path("client.cnf").to_str().unwrap().to_owned();
    openssl(&["req","-x509","-newkey","rsa:2048","-nodes","-keyout",ca_key_s.as_str(),
        "-out",ca_cert_s.as_str(),"-days","3","-config",ca_cfg_s.as_str()]);
    openssl(&["req","-new","-newkey","rsa:2048","-nodes","-keyout",leaf_key_s.as_str(),
        "-out",csr_s.as_str(),"-subj","/CN=untrusted-display-name"]);
    openssl(&["x509","-req","-in",csr_s.as_str(),"-CA",ca_cert_s.as_str(),
        "-CAkey",ca_key_s.as_str(),"-CAcreateserial","-out",leaf_s.as_str(),"-days","2",
        "-extfile",leaf_cfg_s.as_str(),"-extensions","v3_client"]);
    #[cfg(unix)] {
        use std::os::unix::fs::PermissionsExt;
        for p in [ca_key,leaf_key] {
            fs::set_permissions(p,fs::Permissions::from_mode(0o600)).unwrap();
        }
    }
}

#[test]
fn tdd_rust_sdk_sends_real_client_certificate_over_verified_tls13() {
    let f = Temp::new();
    test_identity(&f);
    // A real Rustls server verifier requires the client certificate rooted in
    // the test-only CA, and checks the clientAuth EKU and certificate lifetime.
    let mut roots = rustls::RootCertStore::empty();
    let roots_pem = fs::read(f.path("ca.pem")).unwrap();
    for cert in rustls_pemfile::certs(&mut roots_pem.as_slice()) {
        roots.add(cert.unwrap()).unwrap();
    }
    let verifier = rustls::server::WebPkiClientVerifier::builder(Arc::new(roots))
        .build().unwrap();
    let server_cert = fs::read(fixture_path("server-cert.pem")).unwrap();
    let server_key = fs::read(fixture_path("server-key.pem")).unwrap();
    let certs = rustls_pemfile::certs(&mut server_cert.as_slice())
        .collect::<Result<Vec<_>,_>>().unwrap();
    let private = rustls_pemfile::private_key(&mut server_key.as_slice()).unwrap().unwrap();
    let server_config = rustls::ServerConfig::builder_with_provider(
        Arc::new(rustls::crypto::ring::default_provider()))
        .with_protocol_versions(&[&rustls::version::TLS13]).unwrap()
        .with_client_cert_verifier(verifier).with_single_cert(certs,private).unwrap();

    let listener = TcpListener::bind("127.0.0.1:0").unwrap();
    let addr = listener.local_addr().unwrap();
    let server_thread = thread::spawn(move || {
        let (tcp, _) = listener.accept().unwrap();
        tcp.set_read_timeout(Some(Duration::from_secs(4))).unwrap();
        tcp.set_write_timeout(Some(Duration::from_secs(4))).unwrap();
        let conn = rustls::ServerConnection::new(Arc::new(server_config)).unwrap();
        let mut tls = rustls::StreamOwned::new(conn,tcp);
        let hello = read_frame(&mut tls).expect("client must send HELLO after verified TLS handshake");
        assert_eq!(hello.operation, Operation::Hello);
        assert_eq!(&hello.payload[..4], &[1,0,0,32]);
        assert_eq!(&hello.payload[4..], &TOKEN);
        assert!(tls.conn.peer_certificates().is_some_and(|certs| certs.len()==1),
            "test TLS server did not verify a client certificate");
        write_frame(&mut tls,&Frame::response(Operation::Hello,hello.request_id,0,vec![1,0])).unwrap();
        tls.flush().unwrap();
        let ping = read_frame(&mut tls).unwrap();
        assert_eq!(ping.operation, Operation::Ping);
        write_frame(&mut tls,&Frame::response(Operation::Ping,ping.request_id,0,vec![])).unwrap();
        tls.flush().unwrap();
        tls.conn.send_close_notify();
        let _ = tls.flush();
    });
    let mut client = LocalClient::connect_mtls(addr,"localhost",
        &fixture_path("root-ca.pem"),&f.path("client.pem"),&f.path("client.key"),&TOKEN)
        .expect("client must present a verified client cert to a real TLS1.3 server");
    client.ping().unwrap();
    server_thread.join().unwrap();
}

#[test]
fn tdd_rust_sdk_rejects_remote_destination_and_bad_private_key_before_network() {
    let f = Temp::new();
    test_identity(&f);
    let ca = fixture_path("root-ca.pem");
    let cert = f.path("client.pem");
    let key = f.path("client.key");
    let remote = "192.0.2.9:8790".parse().unwrap();
    assert!(matches!(LocalClient::connect_mtls(remote,"localhost",
        &ca,&cert,&key,&TOKEN),Err(ClientError::RemoteForbidden)));

    let local = "127.0.0.1:1".parse().unwrap(); // no listener: file errors must happen first
    let mut invalid = f.path("invalid.key");
    fs::write(&invalid,b"not a PEM private key").unwrap();
    assert!(matches!(LocalClient::connect_mtls(local,"localhost",
        &ca,&cert,&invalid,&TOKEN),Err(ClientError::TlsConfig)));
    invalid = f.path("huge.key");
    fs::write(&invalid,vec![b'x';65*1024]).unwrap();
    assert!(matches!(LocalClient::connect_mtls(local,"localhost",
        &ca,&cert,&invalid,&TOKEN),Err(ClientError::TlsConfig)));
    assert!(matches!(LocalClient::connect_mtls(local,"localhost",
        &ca,&cert,&f.path("missing.key"),&TOKEN),Err(ClientError::TlsConfig)));
    assert!(matches!(LocalClient::connect_mtls(local,"localhost",
        &ca,&f.path("missing.cert"),&key,&TOKEN),Err(ClientError::TlsConfig)));
    assert!(matches!(LocalClient::connect_mtls(local,"localhost",
        &f.path("missing.ca"),&cert,&key,&TOKEN),Err(ClientError::TlsConfig)));
    // Even a valid unrelated private key must not be paired with this leaf.
    let mismatched = fixture_path("server-key.pem");
    assert!(matches!(LocalClient::connect_mtls(local,"localhost",
        &ca,&cert,&mismatched,&TOKEN),Err(ClientError::TlsConfig)));
    #[cfg(unix)] {
        use std::os::unix::fs::{symlink,PermissionsExt};
        fs::set_permissions(&key,fs::Permissions::from_mode(0o644)).unwrap();
        assert!(matches!(LocalClient::connect_mtls(local,"localhost",
            &ca,&cert,&key,&TOKEN),Err(ClientError::TlsConfig)));
        fs::set_permissions(&key,fs::Permissions::from_mode(0o600)).unwrap();
        let link = f.path("symlink.key");
        symlink(&key,&link).unwrap();
        assert!(matches!(LocalClient::connect_mtls(local,"localhost",
            &ca,&cert,&link,&TOKEN),Err(ClientError::TlsConfig)));
        let ca_link = f.path("symlink.ca");
        symlink(&ca,&ca_link).unwrap();
        assert!(matches!(LocalClient::connect_mtls(local,"localhost",
            &ca_link,&cert,&key,&TOKEN),Err(ClientError::TlsConfig)));
    }
}
